/* MUTANT: one refusal broken on purpose. The gate MUST go red against this
 * file. Generated by mut/make.py; never edited by hand.
 */
/* <ov-datablock> - a surveillance track whose every field says how it is known.
 *
 * For aegis, terminal, vector, industrial and cyber. Drawn as the TRACK, not a
 * label: the trail of recent fixes on a small scope, each mark shaped by how
 * that fix was known, the track symbol at the head, and a short tag beside it
 * whose fields carry the same marks as their sources. A track that stops being
 * measured is SEEN thinning out behind its symbol.
 *
 *   <ov-datablock label="SECTOR 12" src="models/datablock-coast.json" coast-after="12"></ov-datablock>
 *   el.track = {
 *     callsign: 'UAL123', identity: 'friend', course: 270, speed: 450,
 *     status: { mono: false, tentative: false, coasting: false, fromCoast: false },
 *     fixes: [{ x: 0, y: 0, age: 4, source: 'multi' }, ...],   // NM east/north, seconds old
 *     levels: {
 *       reported: { value: 350, source: 'mode-c', validated: true },
 *       cleared: { value: 370, readback: false },
 *       selected: { value: 390 },
 *     },
 *     sensors: [{ kind: 'psr', supported: true, age: 3 }, { kind: 'ads-b', supported: false }],
 *   };
 *
 *   fix source   mark             what it claims
 *   multi        solid circle     measured by two or more sensors
 *   mono         solid diamond    measured by one sensor
 *   reported     hollow square    the aircraft said so (ADS-B, Mode C)
 *   coast        cross            extrapolated: nobody measured it
 *
 * ⚠️ FOUR SHAPES, NOT FOUR VARIATIONS OF A CIRCLE. The first cut drew a dot, a
 * ring with a centre dot, a ring and a dashed ring, and at trail size they
 * read as the same mark. The difference between measured and told is the
 * whole element, so it has to survive a glance.
 *
 * ── THE REFUSAL ───────────────────────────────────────────────────────────
 *
 * 🔴 A FIELD NOBODY MEASURED IS NEVER DRAWN AS MEASURED. Each fix and each
 * level carries the mark of its source, and the slot a measured value lives in
 * refuses anything that was not.
 *
 * And six that follow from it:
 *
 * 1. A COASTING TRACK DOES NOT CARRY IDENTITY. The callsign slot reads CST with
 *    the coast's age: FAA JO 7110.65 5-3-4, "Use the data block to maintain
 *    target identity unless it is in a coast status". With `coast-after`, a
 *    track whose last measured fix is older than that is coasting whatever its
 *    status says (ASTERIX CAT062 I062/080 CST: "Age of the last received track
 *    update is higher than system dependent threshold"), and the element draws
 *    no position it was not given: the head stays on the last fix, ringed.
 * 2. A LEVEL FROM A DEFAULT, A LOOK-UP OR "HEIGHT FROM COVERAGE" IS NOT A
 *    MEASURED LEVEL. The measured slot reads NO MEASURED LEVEL and the value is
 *    printed apart, named by its source (CAT062 I062/080 SRC). INFERRED: the
 *    standard defines the source codes, not this display rule.
 * 3. A LEVEL AFTER A START FROM COAST IS UNVALIDATED until confirmed: JO
 *    7110.65 5-2-15, "Ensure that Mode C altitude readouts are valid after ...
 *    Track start from coast/frozen status."
 * 4. A SENSOR THE SYSTEM DOES NOT HAVE READS n/a, NOT FRESH. CAT062 I062/290
 *    note 3: "If the system does not support the technology, default value is
 *    meaningless." A supported sensor with no age is NO DATA.
 * 5. CLEARED, SELECTED AND REPORTED ARE THREE FIELDS. A selected level that
 *    differs from the cleared one is flagged, and a selected level never stands
 *    in for a read-back: "careful listening to pilot read-back is important and
 *    cannot be replaced by waiting for the new selected altitude setting"
 *    (SKYbrary, secondary).
 * 6. A TENTATIVE OR MONO-SENSOR TRACK SAYS SO (I062/080 CNF and MON).
 *
 * Identity comes from ov-track's rules: an unclassified track is pending, never
 * a default friend.
 *
 * Drawn on each update and at most once a second while on screen, for ages.
 * Nothing asks for an animation frame.
 */

import { define, watchSeen, isSeen, whenArrived } from '../../../src/ov-core.js';
import { resolveTrack, trackSymbol } from '../../../src/ov-track.js';
import '../../../src/ov-source.js';

const FIX_SOURCES = ['multi', 'mono', 'reported', 'coast'];
// Level sources: measured by the ground, reported by the aircraft, or derived.
const LEVEL_SOURCE = {
  '3d-radar': ['multi', '3D RADAR'], mlat: ['multi', 'MLAT'], triangulation: ['multi', 'TRIANGULATION'],
  'mode-c': ['reported', 'MODE C'], gnss: ['reported', 'GNSS'],
  coverage: ['derived', 'RADAR COVERAGE'], lookup: ['derived', 'SPEED LOOK-UP'], default: ['derived', 'DEFAULT HEIGHT'],
};
const SENSOR = { psr: 'PSR', ssr: 'SSR', 'mode-s': 'MODE S', 'ads-b': 'ADS-B', mlat: 'MLAT' };
const W = 400;
const H = 250;

const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const setText = (el, t) => { if (el && el.textContent !== t) el.textContent = t; };
const setAttr = (el, k, v) => {
  if (!el) return;
  if (v === null) { if (el.hasAttribute(k)) el.removeAttribute(k); } else if (el.getAttribute(k) !== v) el.setAttribute(k, v);
};
const setStyle = (el, k, v) => { if (el && el.style.getPropertyValue(k) !== v) el.style.setProperty(k, v); };
const num = (v) => (v === null || v === undefined || v === '' ? null : Number.isFinite(Number(v)) ? Number(v) : null);
const f1 = (v) => v.toFixed(1);
const lvl = (v) => String(Math.round(v)).padStart(3, '0');

/* Seconds -> "12s", "4m 10s", "3h 05m". */
export function span(s) {
  const n = Math.max(0, Math.floor(s));
  if (n < 60) return `${n}s`;
  if (n < 3600) return `${Math.floor(n / 60)}m ${String(n % 60).padStart(2, '0')}s`;
  return `${Math.floor(n / 3600)}h ${String(Math.floor(n / 60) % 60).padStart(2, '0')}m`;
}

class OvDatablock extends HTMLElement {
  static observedAttributes = ['label', 'src', 'source', 'coast-after'];

  /* Our clock, in epoch ms. Replaceable so a test can drive time. */
  static now = () => Date.now();

  constructor() {
    super();
    this._track = undefined;
    this._at = null;
    this._malformed = 0;
    this._coasting = null;
  }

  connectedCallback() {
    if (!this._built) this.build();
    this.fetchSrc();
    this.bindSource();
    this.render();
    // 🔴 A LIVE LOOP WAITS FOR THE PAGE: ov-core holds timers until arrival.
    if (!this._unarrive) this._unarrive = whenArrived(() => this.startTicking());
    if (!this._unwatch) this._unwatch = watchSeen(this, () => this.render());
  }

  startTicking() {
    if (this._timer || !this.isConnected) return;
    this._timer = setInterval(() => { if (isSeen(this)) this.render(); }, 1000);
  }

  disconnectedCallback() {
    clearInterval(this._timer);
    this._timer = 0;
    if (this._unarrive) this._unarrive();
    this._unarrive = null;
    if (this._unwatch) this._unwatch();
    this._unwatch = null;
    if (this.unsub) this.unsub();
    this.unsub = null;
  }

  attributeChangedCallback(name) {
    if (!this._built) return;
    if (name === 'src') { this.fetchSrc(); return; }
    if (name === 'source') this.bindSource();
    this.render();
  }

  /* 🔴 A FETCH THAT FAILS LEAVES NO TRACK, NOT A STALE ONE. */
  async fetchSrc() {
    const src = this.getAttribute('src');
    if (!src) return;
    let data = null;
    try {
      const r = await fetch(src);
      if (!r.ok) throw new Error(String(r.status));
      data = await r.json();
    } catch {
      data = null;
    }
    if (this.getAttribute('src') !== src) return;
    this.track = data;
  }

  bindSource() {
    if (this.unsub) this.unsub();
    this.unsub = null;
    const name = this.getAttribute('source');
    if (!name || !window.Overscan?.subscribe) return;
    this.unsub = window.Overscan.subscribe(name, (t) => { if (t !== null && t !== undefined) this.track = t; });
  }

  /* ---- the door ------------------------------------------------------- */

  set track(t) {
    this._track = t && typeof t === 'object' ? t : null;
    this._at = this._track ? OvDatablock.now() : null;
    this.render();
  }

  get track() { return this._track; }

  coastAfter() {
    const v = Number(this.getAttribute('coast-after'));
    return this.hasAttribute('coast-after') && Number.isFinite(v) && v > 0 ? v : null;
  }

  /* ---- what is true right now ----------------------------------------- */

  read(now) {
    const t = this._track;
    if (!t) return null;
    const since = (now - this._at) / 1000;   // seconds since this report arrived
    this._malformed = 0;
    const fixes = [];
    for (const f of Array.isArray(t.fixes) ? t.fixes : []) {
      const x = num(f?.x);
      const y = num(f?.y);
      const age = num(f?.age);
      if (x === null || y === null || age === null || !FIX_SOURCES.includes(f.source)) { this._malformed += 1; continue; }
      fixes.push({ x, y, age: age + since, source: f.source });
    }
    fixes.sort((a, b) => b.age - a.age);   // oldest first, head last
    const measured = fixes.filter((f) => f.source !== 'coast');
    const lastMeasured = measured[measured.length - 1] || null;
    const st = t.status && typeof t.status === 'object' ? t.status : {};
    const limit = this.coastAfter();
    const selfCoast = limit !== null && (!lastMeasured || lastMeasured.age > limit);
    const coasting = st.coasting === true || selfCoast;
    const coastAge = lastMeasured ? lastMeasured.age : null;

    const L = t.levels && typeof t.levels === 'object' ? t.levels : {};
    const rep = L.reported && typeof L.reported === 'object' ? L.reported : null;
    const src = rep && Object.hasOwn(LEVEL_SOURCE, rep.source) ? LEVEL_SOURCE[rep.source] : null;
    const repValue = num(rep?.value);
    const levels = {
      measured: null, derived: null, unvalidated: false, sourceWord: src ? src[1] : null, mark: src ? src[0] : 'none',
      cleared: num(L.cleared?.value), readback: L.cleared?.readback === true || num(L.selected?.value) === num(L.cleared?.value), selected: num(L.selected?.value),  // MUTANT
    };
    if (repValue !== null && src && src[0] !== 'derived') {
      levels.measured = repValue;
      levels.unvalidated = (st.fromCoast === true || rep.validated === false) && rep.validated !== true;
    } else if (repValue !== null && src && src[0] === 'derived') {
      levels.derived = repValue;
    }
    levels.mismatch = levels.cleared !== null && levels.selected !== null && levels.cleared !== levels.selected;

    const sensors = (Array.isArray(t.sensors) ? t.sensors : []).filter((s) => s && Object.hasOwn(SENSOR, s.kind)).map((s) => {
      const age = num(s.age);
      if (s.supported === false) return { kind: s.kind, word: 'n/a', state: 'unsupported' };
      if (age === null) return { kind: s.kind, word: 'NO DATA', state: 'none' };
      return { kind: s.kind, word: span(age + since), state: 'fresh' };
    });

    return {
      callsign: typeof t.callsign === 'string' && t.callsign.trim() ? t.callsign.trim().toUpperCase() : null,
      ident: resolveTrack({ identity: t.identity, course: t.course, speed: t.speed, dimension: 'air' }),
      fixes, lastMeasured, coasting, selfCoast, coastAge,
      mono: st.mono === true, tentative: st.tentative === true,
      levels, sensors, speed: num(t.speed),
    };
  }

  get report() {
    const r = this.read(OvDatablock.now());
    return r && {
      callsign: r.coasting ? null : r.callsign, coasting: r.coasting, selfCoast: r.selfCoast,
      levels: r.levels, sensors: r.sensors, fixes: r.fixes.length, malformed: this._malformed,
    };
  }

  /* ---- drawing -------------------------------------------------------- */

  build() {
    this._built = true;
    this.innerHTML = '<div class="ov-head">'
      + '<span class="ov-aside ov-head__name ov-datablock__label"></span>'
      + '<span class="ov-aside ov-head__note ov-datablock__key">● MEASURED · ◆ ONE SENSOR · □ REPORTED · ✕ EXTRAPOLATED</span></div>'
      // The tag is the scope's SIBLING inside a view, not its child: under
      // 380px the tag leaves the picture and sits below it (CSS container
      // query), because overlaid on a small scope it covered the whole trail.
      + '<div class="ov-datablock__view"><div class="ov-datablock__scope">'
      + `<svg class="ov-datablock__svg" viewBox="0 0 ${W} ${H}" aria-hidden="true"><g class="ov-datablock__grid"></g><g class="ov-datablock__trail"></g><g class="ov-datablock__head"></g><line class="ov-datablock__leader"/></svg>`
      + '<div class="ov-datablock__scale"></div>'
      + '<div class="ov-datablock__none"></div></div>'
      + '<div class="ov-datablock__tag">'
      + '<div class="ov-datablock__id"><span class="ov-datablock__callsign"></span><span class="ov-datablock__quals"></span></div>'
      + '<div class="ov-aside ov-datablock__was"></div>'
      + '<div class="ov-datablock__levels">'
      + '<span class="ov-datablock__field ov-datablock__measured"><i class="ov-datablock__src"></i><b></b></span>'
      + '<span class="ov-datablock__field ov-datablock__cleared"><b></b></span>'
      + '<span class="ov-datablock__field ov-datablock__selected"><b></b></span></div>'
      + '<div class="ov-datablock__derived"><i class="ov-datablock__src" data-ov-src="derived"></i><b></b></div>'
      + '<div class="ov-datablock__flags"></div>'
      + '<div class="ov-datablock__sensors"></div>'
      + '</div>'
      + '</div>'
      + '<div class="ov-datablock__foot"></div>'
      + '<span class="ov-datablock__say" aria-live="polite"></span>';
    const q = (c) => this.querySelector(`.ov-datablock__${c}`);
    this.$ = {
      label: q('label'), scope: q('scope'), grid: q('grid'), trail: q('trail'), head: q('head'), leader: q('leader'),
      tag: q('tag'), callsign: q('callsign'), quals: q('quals'), was: q('was'),
      measured: q('measured'), cleared: q('cleared'), selected: q('selected'), derived: q('derived'),
      flags: q('flags'), sensors: q('sensors'), scale: q('scale'), none: q('none'), foot: q('foot'), say: q('say'),
    };
    this.setAttribute('role', 'group');
  }

  render() {
    if (!this._built) return;
    const now = OvDatablock.now();
    const label = this.getAttribute('label') || 'TRACK';
    setText(this.$.label, label);
    const r = this.read(now);
    setAttr(this, 'data-ov-refusal', r ? null : 'unknown');
    setText(this.$.none, r ? '' : 'NO TRACK');
    this.$.tag.hidden = !r;
    if (!r) {
      this.$.trail.innerHTML = '';
      this.$.head.innerHTML = '';
      setAttr(this.$.leader, 'd', null);
      setText(this.$.foot, '');
      setAttr(this, 'aria-label', `${label}: no track`);
      return;
    }

    // Coasting is announced once when it starts and once when it ends.
    if (this._coasting !== null && r.coasting !== this._coasting) {
      this.say(r.coasting ? `${r.callsign || 'track'} coasting, identity not maintained` : `${r.callsign || 'track'} measured again`);
      this.dispatchEvent(new CustomEvent('ov:datablock', { bubbles: true, detail: { coasting: r.coasting, self: r.selfCoast } }));
    }
    this._coasting = r.coasting;
    setAttr(this, 'data-ov-coasting', r.coasting ? 'yes' : null);

    // ---- the scope: fit every fix, equal scale both ways, north up.
    const pts = r.fixes;
    const xs = pts.map((p) => p.x);
    const ys = pts.map((p) => p.y);
    const cx = pts.length ? (Math.min(...xs) + Math.max(...xs)) / 2 : 0;
    const cy = pts.length ? (Math.min(...ys) + Math.max(...ys)) / 2 : 0;
    const spanNm = pts.length ? Math.max(Math.max(...xs) - Math.min(...xs), (Math.max(...ys) - Math.min(...ys)) * (W / H), 2) : 2;
    const k = (W * 0.62) / spanNm;          // px per NM, leaving room for the tag
    const X = (x) => W * 0.42 + (x - cx) * k;
    const Y = (y) => H / 2 - (y - cy) * k;
    let trail = '';
    // One path per fix, its outline chosen by source, so every mark is the
    // same kind of node and only its SHAPE says how it was known.
    const shape = (src, x, y) => {
      if (src === 'multi') return ['circle', `M${f1(x - 4.2)} ${f1(y)}a4.2 4.2 0 1 0 8.4 0a4.2 4.2 0 1 0 -8.4 0Z`];
      if (src === 'mono') return ['diamond', `M${f1(x)} ${f1(y - 5)}L${f1(x + 5)} ${f1(y)}L${f1(x)} ${f1(y + 5)}L${f1(x - 5)} ${f1(y)}Z`];
      if (src === 'reported') return ['square', `M${f1(x - 3.8)} ${f1(y - 3.8)}h7.6v7.6h-7.6Z`];
      return ['cross', `M${f1(x - 4)} ${f1(y - 4)}L${f1(x + 4)} ${f1(y + 4)}M${f1(x + 4)} ${f1(y - 4)}L${f1(x - 4)} ${f1(y + 4)}`];
    };
    pts.forEach((p, i) => {
      const [name, d] = shape(p.source, X(p.x), Y(p.y));
      trail += `<path class="ov-datablock__fix" data-ov-src="${p.source}" data-ov-shape="${name}" data-ov-fix="${i}" d="${d}"/>`;
    });
    if (trail !== this._trailHtml) { this._trailHtml = trail; this.$.trail.innerHTML = trail; }
    const nice = [0.5, 1, 2, 5, 10, 20, 50].find((n) => n * k >= 40) || 50;
    setText(this.$.scale, `▬ ${nice} NM`);
    setStyle(this.$.scale, '--ov-db-scale', `${(nice * k / W) * 100}%`);

    // The symbol stays on the last MEASURED fix: the element does not invent
    // a position. Coast fixes the tracker extrapolated are drawn beyond it.
    const head = pts[pts.length - 1] || null;
    const anchor = r.lastMeasured || head;
    if (anchor) {
      const sym = trackSymbol(r.ident, { scale: 0.42, x: X(anchor.x), y: Y(anchor.y) })
        + (r.coasting ? `<circle class="ov-datablock__coastring" cx="${f1(X(anchor.x))}" cy="${f1(Y(anchor.y))}" r="12"/>` : '');
      if (sym.replace(/ov-track-clip-\d+/g, '') !== this._headKey) {
        this._headKey = sym.replace(/ov-track-clip-\d+/g, '');
        this.$.head.innerHTML = sym;
      }
    }

    // ---- the tag, beside the head, on the side with room.
    const hx = head ? X(head.x) / W : 0.42;
    const hy = head ? Y(head.y) / H : 0.5;
    const right = hx < 0.6;
    setAttr(this.$.tag, 'data-ov-side', right ? 'right' : 'left');
    setStyle(this.$.tag, 'inset-inline-start', right ? `${((hx + 0.06) * 100).toFixed(1)}%` : 'auto');
    setStyle(this.$.tag, 'inset-inline-end', right ? 'auto' : `${((1 - hx + 0.06) * 100).toFixed(1)}%`);
    setStyle(this.$.tag, 'inset-block-start', `${(Math.max(0.04, Math.min(0.55, hy - 0.2)) * 100).toFixed(1)}%`);
    if (head) {
      const lx = right ? (hx + 0.06) * W : (hx - 0.06) * W;
      setAttr(this.$.leader, 'x1', f1(X(head.x)));
      setAttr(this.$.leader, 'y1', f1(Y(head.y)));
      setAttr(this.$.leader, 'x2', f1(lx));
      setAttr(this.$.leader, 'y2', f1(Math.max(0.04, Math.min(0.55, hy - 0.2)) * H + 6));
    }

    // Identity: withheld through a coast.
    setText(this.$.callsign, r.coasting ? `CST ${r.coastAge === null ? 'NO MEASURED FIX' : span(r.coastAge)}` : r.callsign || 'NO CALLSIGN');
    setAttr(this.$.callsign, 'data-ov-tone', r.coasting || !r.callsign ? 'bad' : null);
    setText(this.$.was, r.coasting && r.callsign ? `LAST IDENTIFIED AS ${r.callsign}` : '');
    const quals = [];
    if (r.tentative) quals.push('TENTATIVE');
    if (r.mono) quals.push('MONO');
    setText(this.$.quals, quals.join(' · '));

    // Levels: the measured slot takes only a measured or reported level.
    const lv = r.levels;
    const m = this.$.measured;
    setAttr(m.querySelector('.ov-datablock__src'), 'data-ov-src', lv.measured !== null ? lv.mark : 'none');
    setText(m.querySelector('b'), lv.measured !== null ? `${lvl(lv.measured)}${lv.unvalidated ? ' UNVALIDATED' : ''}` : 'NO MEASURED LEVEL');
    setAttr(m, 'data-ov-tone', lv.measured === null ? 'bad' : lv.unvalidated ? 'note' : null);
    setText(this.$.cleared.querySelector('b'), lv.cleared === null ? '' : `C${lvl(lv.cleared)}${lv.readback ? '' : ' NOT READ BACK'}`);
    setAttr(this.$.cleared, 'data-ov-tone', lv.cleared !== null && !lv.readback ? 'note' : null);
    setText(this.$.selected.querySelector('b'), lv.selected === null ? '' : `S${lvl(lv.selected)}`);
    setAttr(this.$.selected, 'data-ov-tone', lv.mismatch ? 'bad' : null);
    this.$.derived.hidden = lv.derived === null;
    setText(this.$.derived.querySelector('b'), lv.derived === null ? '' : `${lvl(lv.derived)} FROM ${lv.sourceWord}, NOT MEASURED`);
    const flags = [];
    if (lv.mismatch) flags.push(`SELECTED ${lvl(lv.selected)} ≠ CLEARED ${lvl(lv.cleared)}`);
    setText(this.$.flags, flags.join(' · '));

    const sens = r.sensors.map((s) => `<span class="ov-datablock__sensor" data-ov-sensor="${s.kind}" data-ov-state="${s.state}">${SENSOR[s.kind]} ${esc(s.word)}</span>`).join('');
    if (sens !== this._sensHtml) { this._sensHtml = sens; this.$.sensors.innerHTML = sens; }

    const foot = [];
    if (this._malformed) foot.push(`${this._malformed} FIX${this._malformed > 1 ? 'ES' : ''} REFUSED: A FIX NEEDS X, Y, AGE AND A SOURCE`);
    if (!pts.length) foot.push('NO FIXES REPORTED');
    setText(this.$.foot, foot.join(' · '));

    setAttr(this, 'aria-label', `${label}: `
      + (r.coasting ? `coasting ${r.coastAge === null ? '' : span(r.coastAge)}, identity not maintained` : r.callsign || 'no callsign')
      + (lv.measured !== null ? `, level ${lvl(lv.measured)}${lv.unvalidated ? ' unvalidated' : ''}` : ', no measured level')
      + (lv.mismatch ? `, selected ${lvl(lv.selected)} differs from cleared ${lvl(lv.cleared)}` : ''));
  }

  /* Everything said in one task is joined and said once. */
  say(text) {
    const region = this.$?.say;
    if (!region) return;
    (region._ovSay ||= []).push(text);
    if (region._ovSay.length > 1) return;
    queueMicrotask(() => {
      const all = region._ovSay;
      region._ovSay = [];
      region.textContent = '';
      region.textContent = all.join('. ');
    });
  }
}

define('ov-datablock', OvDatablock);

export { OvDatablock };
